import{_ as t,o as a,i as o,a9 as r}from"./chunks/framework.DuwpaNh0.js";const h=JSON.parse('{"title":"DataType.OPAQUE: Where Recursion Stops","description":"","frontmatter":{"title":"DataType.OPAQUE: Where Recursion Stops"},"headers":[],"relativePath":"modules/5-advanced/conductor-interop/3-opaque.md","filePath":"modules/5-advanced/conductor-interop/3-opaque.md","lastUpdated":1787938870000}'),n={name:"modules/5-advanced/conductor-interop/3-opaque.md"};function s(i,e,l,c,u,d){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="datatype-opaque-where-recursion-stops" tabindex="-1"><code>DataType.OPAQUE</code>: where recursion stops <a class="header-anchor" href="#datatype-opaque-where-recursion-stops" aria-label="Permalink to &quot;`DataType.OPAQUE`: where recursion stops&quot;">​</a></h1><p><code>DataType.OPAQUE</code> is the one place an evaluator&#39;s conversion code should <strong>not</strong> try to interpret a value further. Once something is wrapped opaque, it&#39;s handed back out exactly as given — no recursive conversion, no float-narrowing, nothing. This is what makes it safe for a bundle to store an arbitrary cadet-supplied value (a number, a string, another data structure, or a genuinely non-representable JS object) without needing to know or care what it is.</p><p>Note that this doesn&#39;t create an exception to the <a href="./1-numbers.html">&quot;numbers are always floats&quot;</a> rule — a number is converted to a float <em>before</em> it&#39;s wrapped opaque (or before it&#39;s read back out of one), not after. <code>OPAQUE</code> is a boundary for <em>structural</em> recursion, not an escape hatch from the numeric contract.</p><h2 id="summary-the-module-facing-primitives" tabindex="-1">Summary: the module-facing primitives <a class="header-anchor" href="#summary-the-module-facing-primitives" aria-label="Permalink to &quot;Summary: the module-facing primitives&quot;">​</a></h2><p>Per Martin, the module interface should be thought of as offering only:</p><ul><li><strong>numbers</strong> (always floats)</li><li><strong>functions</strong> (untyped — no declared parameter/return types beyond &quot;it&#39;s a function&quot;)</li><li><strong>arrays</strong> (untyped, recursive — includes what SICPy/CS1101S chapter 2 calls &quot;pairs&quot;, see <a href="./2-pairs-and-arrays.html">Pairs and arrays are the same thing</a>)</li><li><strong>null</strong> (Python&#39;s <code>None</code>)</li><li><strong>true/false</strong> (booleans)</li></ul><p>Two more exist in practice and are worth naming even though they weren&#39;t part of the original five:</p><ul><li><strong>strings</strong> (<code>DataType.CONST_STRING</code>) — real and load-bearing (e.g. <code>midi</code>&#39;s note names, accidentals).</li><li><strong><code>DataType.OPAQUE</code></strong> — for a value that isn&#39;t decomposable into the above at all (a JS object a bundle wants to hand back to the cadet as an inert handle — <code>rune</code>&#39;s graphics objects, <code>binary_tree</code>&#39;s stored payload, etc.), or where the module simply doesn&#39;t want the evaluator trying to interpret it.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">Complex numbers</p><p>Complex numbers are explicitly <strong>not</strong> supported crossing a module boundary. This is really an aside specific to Python — of the languages Conductor currently supports, only Python has complex numbers as a primitive at all.</p></div><p>An opaque value that&#39;s genuinely visual (a <code>rune</code> scene graph, say) can optionally carry its own stepper-thumbnail renderer, invisible to the evaluator and to cadet code — see <a href="./6-opaque-thumbnails.html">Stepper thumbnails for opaque values</a>.</p>',10)]))}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
